def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    props = s.get('element_properties') or {}
    volume = (s.get('lattice') or {}).get('volume_A3') or 0.0
    if volume <= 0.0:
        return 0.0
    total = 0.0
    for site in sites:
        p = props.get(site.get('element')) or {}
        radius = max(0.1, p.get('covalent_radius_A') or 1.3)
        occupancy = max(0.0, site.get('occupancy', 1.0) or 0.0)
        total += occupancy * radius ** 3
    return 4.0 * pi * total / (3.0 * volume)

def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    props = s.get('element_properties') or {}
    radii = [max(0.1, (props.get(x.get('element')) or {}).get('covalent_radius_A') or 1.3) for x in sites]
    occ = [max(0.0, x.get('occupancy', 1.0) or 0.0) for x in sites]
    best = 0.0
    for bond in s.get('neighbors') or []:
        i = bond.get('i', -1)
        j = bond.get('j', -1)
        d = bond.get('distance_A') or 0.0
        if 0 <= i < len(sites) and 0 <= j < len(sites) and d > 0.0 and occ[i] * occ[j] > 0.0:
            value = d / (radii[i] + radii[j])
            if best == 0.0 or value < best:
                best = value
    return best

