def feature(s):
    if not s:
        return 0.0
    props = s.get('element_properties') or {}
    weight = 0.0
    sr = 0.0
    se = 0.0
    srr = 0.0
    see = 0.0
    sre = 0.0
    for element, fraction in (s.get('composition') or {}).items():
        p = props.get(element) or {}
        radius = p.get('covalent_radius_A')
        en = p.get('eneg')
        if fraction is not None and fraction > 0.0 and radius is not None and en is not None:
            weight += fraction
            sr += fraction * radius
            se += fraction * en
            srr += fraction * radius * radius
            see += fraction * en * en
            sre += fraction * radius * en
    if weight <= 0.0:
        return 0.0
    vr = max(0.0, srr / weight - (sr / weight) ** 2)
    ve = max(0.0, see / weight - (se / weight) ** 2)
    if vr * ve <= 1e-20:
        return 0.0
    covariance = sre / weight - sr * se / weight ** 2
    return max(-1.0, min(1.0, covariance / sqrt(vr * ve)))

